package com.eidolon.sc.mobile;
import android.content.Context;import androidx.work.*;import java.util.concurrent.TimeUnit;import org.json.*;
/** Android wake-ups are approximate. One durable task is claimed before each model request. */
final class SocialScheduler {
 static void refresh(Context c){try(ChatStore s=new ChatStore(c)){WorkManager work=WorkManager.getInstance(c);JSONObject cfg=SocialStore.config(s);if(SocialStore.count(s,"SELECT count(*) FROM social_posts")>0)work.enqueueUniquePeriodicWork("eidolon-social-maintenance",ExistingPeriodicWorkPolicy.KEEP,new PeriodicWorkRequest.Builder(SocialCleanupWorker.class,1,TimeUnit.DAYS).build());else work.cancelUniqueWork("eidolon-social-maintenance");if(cfg.getBoolean("enabled")){work.enqueueUniquePeriodicWork("eidolon-social-tick",ExistingPeriodicWorkPolicy.KEEP,new PeriodicWorkRequest.Builder(SocialWorker.class,15,TimeUnit.MINUTES).setConstraints(new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()).build());JSONArray a=SocialStore.pending(s);long now=System.currentTimeMillis();for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);if(row.getLong("expires")<=now)continue;work.enqueueUniqueWork("eidolon-social-task-"+row.getString("id"),ExistingWorkPolicy.KEEP,new OneTimeWorkRequest.Builder(SocialWorker.class).setInitialDelay(Math.max(1000,row.getLong("due")-now),TimeUnit.MILLISECONDS).setConstraints(new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()).build());}}
  else work.cancelUniqueWork("eidolon-social-tick");}catch(Exception e){android.util.Log.w("EidolonSocial","Local schedule unavailable");}}
 static void check(Context c){try{WorkManager.getInstance(c).enqueueUniqueWork("eidolon-social-check",ExistingWorkPolicy.KEEP,new OneTimeWorkRequest.Builder(SocialWorker.class).setConstraints(new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()).build());}catch(Exception e){android.util.Log.w("EidolonSocial","Local check unavailable");}}
}
